begin;
create extension if not exists pgtap with schema extensions;
set local search_path=extensions,public,pg_catalog;
select plan(14);
select has_table('app','coach_availability_policies','owner policy has an authoritative revision');
select has_table('app','coach_availability_date_overrides','whole dates have independent replacement records');
select has_table('app','coach_availability_operations','exact retries have durable scoped receipts');
select has_column('app','coach_availability_slots','closed_policy_revision','policy closure provenance permits fresh successors');
select ok((select indexdef like '%status <> %withdrawn%' from pg_indexes where schemaname='app' and indexname='coach_availability_slots_rule_occurrence_key'),'terminal occurrences do not prevent fresh successor identities');
select is((select count(*)::integer from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='app' and c.relname in ('coach_availability_policies','coach_availability_date_overrides','coach_availability_operations') and c.relrowsecurity and c.relforcerowsecurity),3,'all policy tables force row security');
select ok(not has_table_privilege('app_runtime','app.coach_availability_policies','select,insert,update,delete') and not has_table_privilege('app_runtime','app.coach_availability_date_overrides','select,insert,update,delete') and not has_table_privilege('app_runtime','app.coach_availability_operations','select,insert,update,delete'),'runtime cannot bypass scoped policy functions');
select ok(has_function_privilege('app_runtime','app.save_owned_effective_coach_availability(jsonb)','execute') and has_function_privilege('app_runtime','app.preview_owned_effective_coach_availability(jsonb)','execute') and has_function_privilege('app_runtime','app.owned_effective_coach_availability(date,date)','execute'),'runtime has narrow actor-checked save, preview and read entry points');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join (values('anon'),('authenticated'),('service_role')) roles(name) where n.nspname='app' and p.proname in ('save_owned_effective_coach_availability','preview_owned_effective_coach_availability','owned_effective_coach_availability') and has_function_privilege(roles.name,p.oid,'execute')),'browser roles cannot call owner policy entry points');
select ok(not has_function_privilege('app_runtime','app.availability_enter()','execute') and not has_function_privilege('app_runtime','app.effective_coach_hours(uuid,uuid,date)','execute') and not has_function_privilege('app_runtime','app.create_coach_booking_request_before_effective(uuid)','execute') and not has_function_privilege('app_runtime','app.accept_coach_booking_request_before_effective(uuid)','execute'),'internal helpers and historical request bypasses remain denied');
select throws_ok($$select app.save_owned_effective_coach_availability('{}')$$,'P0001','coach availability actor is invalid','policy save requires verified actor context');
select ok(app.availability_in_horizon('2026-11-23 22:00+01','2026-11-23 23:00+01','2026-10-25 00:00+02'),'29th following Berlin date survives the autumn clock change');
select ok(not app.availability_in_horizon('2026-11-24 00:00+01','2026-11-24 01:00+01','2026-10-25 00:00+02'),'30th following date is excluded');
select ok(not app.availability_in_horizon(null,null,clock_timestamp()) and not app.availability_in_horizon(clock_timestamp(),clock_timestamp()+interval '1 hour',clock_timestamp()),'null and elapsed starts never establish capacity');
select * from finish();
rollback;
